LABELS = {'NRC_VAD_valence_mean': 'NRC-VAD: Valence, sentence avg. (pleasant ↔ unpleasant)', 'NRC_VAD_valence': 'NRC-VAD: Valence, per-word (pleasant ↔ unpleasant)', 'NRC_VAD_dominance_mean': 'NRC-VAD: Dominance, sentence avg. (in-control ↔ powerless)', 'NRC_VAD_dominance': 'NRC-VAD: Dominance, per-word (in-control ↔ powerless)', 'AGENCYCOMM_AGENCY': 'Agency–Communion lexicon: agency (action, capability)', 'AGENCYCOMM_COMMUNION': 'Agency–Communion lexicon: communion (connection, warmth)', 'EMPATH_politics': 'Empath topic: politics', 'NRC_OPT_opt': 'NRC Optimism/Pessimism: optimism score', 'EMFD_IngroupVirtue': 'Moral Foundations (eMFD): loyalty: virtue (solidarity)', 'EMFD_IngroupVice': 'Moral Foundations (eMFD): loyalty: vice (betrayal)', 'LIWC_posemo': 'LIWC: positive-emotion words', 'LIWC_negemo': 'LIWC: negative-emotion words', 'LIWC_cogproc': 'LIWC: cognitive-processing words (reasoning, causation)', 'NRC_EMO_negative': 'NRC Emotion Lexicon: negative-emotion words', 'NRC_EMO_positive': 'NRC Emotion Lexicon: positive-emotion words', 'NRC_EMO_fear': 'NRC Emotion Lexicon: fear words', 'NRC_EMO_sadness': 'NRC Emotion Lexicon: sadness words', 'NRC_AFFINT_fear': 'NRC Affect Intensity: fear', 'NRC_AFFINT_sadness': 'NRC Affect Intensity: sadness', 'NRC_AFFINT_anger': 'NRC Affect Intensity: anger', 'NRC_HASHSENT_sent': 'NRC Hashtag Sentiment score', 'EMPATH_suffering': 'Empath topic: suffering', 'EMFD_CareVice': 'Moral Foundations (eMFD): care/harm: vice (harm)', 'EMFD_CareVirtue': 'Moral Foundations (eMFD): care/harm: virtue (compassion)', 'EMFD_PurityVice': 'Moral Foundations (eMFD): purity/sanctity: vice (degradation)', 'MIND_Experience': 'Mind-perception: experience (feelings, sensation)', 'MIND_MindOverall': 'Mind-perception: overall mental-state attribution', 'MFD_Virtue': 'Moral Foundations Dictionary: virtue (general)', 'MFD_IngroupVice': 'Moral Foundations Dictionary: loyalty: vice (betrayal)', 'MFD_IngroupVirtue': 'Moral Foundations Dictionary: loyalty: virtue (solidarity)', 'GENDER_feminine': 'Gender Decoder: feminine-coded words', 'EMPATH_children': 'Empath topic: children', 'EMPATH_negative_emotion': 'Empath topic: negative emotion', 'EMPATH_positive_emotion': 'Empath topic: positive emotion', 'EMPATH_journalism': 'Empath topic: journalism / media', 'EMPATH_reading': 'Empath topic: reading', 'EMPATH_banking': 'Empath topic: banking / finance', 'EMPATH_dispute': 'Empath topic: dispute / conflict', 'EMPATH_school': 'Empath topic: school', 'EMPATH_internet': 'Empath topic: internet', 'EMPATH_philosophy': 'Empath topic: philosophy', 'EMPATH_money': 'Empath topic: money', 'EMPATH_trust': 'Empath topic: trust', 'EMPATH_wedding': 'Empath topic: wedding / marriage', 'EMPATH_love': 'Empath topic: love', 'EMPATH_family': 'Empath topic: family', 'EMPATH_healing': 'Empath topic: healing', 'EMPATH_health': 'Empath topic: health', 'EMPATH_injury': 'Empath topic: injury', 'EMPATH_medical_emergency': 'Empath topic: medical emergency', 'EMPATH_music': 'Empath topic: music', 'EMPATH_musical': 'Empath topic: music (instruments)', 'EMPATH_writing': 'Empath topic: writing', 'EMPATH_stealing': 'Empath topic: stealing / theft', 'EMPATH_violence': 'Empath topic: violence', 'EMPATH_sadness': 'Empath topic: sadness', 'EMPATH_college': 'Empath topic: college', 'EMPATH_affection': 'Empath topic: affection'}

def human_label(cat):
    if cat in LABELS:
        return LABELS[cat]
    fam_map = {'NRC_VAD': 'NRC-VAD', 'NRC_EMO': 'NRC Emotion Lexicon', 'NRC_AFFINT': 'NRC Affect Intensity', 'NRC_OPT': 'NRC Optimism/Pessimism', 'NRC_HASHSENT': 'NRC Hashtag Sentiment', 'EMFD': 'Moral Foundations (eMFD)', 'MFD': 'Moral Foundations Dictionary', 'EMPATH': 'Empath topic', 'LIWC': 'LIWC', 'MIND': 'Mind-perception', 'AGENCYCOMM': 'Agency–Communion lexicon', 'GENDER': 'Gender Decoder', 'AGEGENDER': 'Age/Gender predictor', 'CONCR': 'Concreteness'}
    for (prefix, fam) in sorted(fam_map.items(), key=lambda x: -len(x[0])):
        if cat.startswith(prefix + '_'):
            rest = cat[len(prefix) + 1:].replace('_', ' ')
            return f'{fam}: {rest}'
    return cat.replace('_', ' ')
